<script setup lang="ts">
import { Link } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import { CheckCircle2, CreditCard, ExternalLink, ReceiptText, WalletCards } from '@lucide/vue';
type Invoice = { id: number; title: string; payable: number; paid: number; outstanding: number; due_date: string; status: string; payment_token: string; athlete: { name: string; membership_number: string }; team: string | null };
defineProps<{ invoices: Invoice[]; summary: { total: number; paid: number; outstanding: number } }>();
const money = (value: number) => new Intl.NumberFormat('fa-IR').format(value);
const dateLabel = (value: string) => new Intl.DateTimeFormat('fa-IR', { day: 'numeric', month: 'long', year: 'numeric' }).format(new Date(`${value}T12:00:00`));
const statusLabel = (value: string) => ({ paid: 'تسویه‌شده', partial: 'پرداخت بخشی', unpaid: 'پرداخت‌نشده', overdue: 'سررسید گذشته' }[value] || value);
</script>
<template><AppLayout title="شهریه و پرداخت‌های من" eyebrow="صورتحساب ورزشکار" active="athlete"><section class="mb-5 grid gap-4 sm:grid-cols-3"><article class="access-stat"><div><span>مجموع صورتحساب</span><strong class="text-lg">{{ money(summary.total) }}</strong></div><ReceiptText :size="22" /></article><article class="access-stat"><div><span>پرداخت‌شده</span><strong class="text-lg">{{ money(summary.paid) }}</strong></div><CheckCircle2 :size="22" /></article><article class="access-stat"><div><span>مانده قابل پرداخت</span><strong class="text-lg">{{ money(summary.outstanding) }}</strong></div><WalletCards :size="22" /></article></section><div class="grid gap-4 lg:grid-cols-2"><article v-for="invoice in invoices" :key="invoice.id" class="panel-flat p-5"><div class="flex items-start justify-between gap-3"><div><p class="section-kicker">{{ invoice.athlete.name }} · {{ invoice.team }}</p><h2 class="mt-2 text-sm font-black">{{ invoice.title }}</h2><p class="mt-1 text-[9px] text-[#849098]">سررسید {{ dateLabel(invoice.due_date) }}</p></div><span :class="invoice.status === 'paid' ? 'tag-ok' : invoice.status === 'overdue' ? 'tag-danger' : 'tag-warn'">{{ statusLabel(invoice.status) }}</span></div><div class="my-5 grid grid-cols-3 divide-x divide-x-reverse divide-[#e2e5e6] border-y border-[#e2e5e6] py-4 text-center"><div><span class="text-[8px] text-[#849098]">مبلغ</span><strong class="mt-1 block text-[11px]">{{ money(invoice.payable) }}</strong></div><div><span class="text-[8px] text-[#849098]">پرداخت</span><strong class="mt-1 block text-[11px] text-[#24745d]">{{ money(invoice.paid) }}</strong></div><div><span class="text-[8px] text-[#849098]">مانده</span><strong class="mt-1 block text-[11px] text-[#c54f34]">{{ money(invoice.outstanding) }}</strong></div></div><a v-if="invoice.outstanding" :href="`/pay/${invoice.payment_token}`" class="primary-sport-button w-full"><CreditCard :size="16" /> پرداخت آنلاین <ExternalLink :size="13" /></a><div v-else class="flex items-center justify-center gap-2 bg-[#edf7f1] p-3 text-[10px] font-black text-[#24745d]"><CheckCircle2 :size="16" /> این صورتحساب تسویه شده است</div></article><p v-if="!invoices.length" class="panel-flat p-10 text-center text-[10px] text-[#849098]">صورتحسابی برای این حساب وجود ندارد.</p></div></AppLayout></template>
